<section class="page-banner"><div class="container"><a href="<?= e(url('admin/clubs')) ?>" class="back-link">← Manage clubs</a><div class="section-label">CLUB ADMINISTRATION</div><h1><?= $club?'Edit club':'Create club' ?></h1><p>Societies created here are demonstration records until reviewed and published by an actual institution.</p></div></section><section class="section container narrow"><div class="card panel"><form method="post" class="form-stack" action="<?= e(url('admin/club/save')) ?>"><?= csrf_field() ?><?php if($club): ?><input type="hidden" name="id" value="<?= (int)$club['id'] ?>"><?php endif; ?><label>Club name<input required name="name" minlength="4" maxlength="150" value="<?= e($club['name']??'') ?>"></label><label>Category<input required name="category" minlength="3" maxlength="80" placeholder="Technology, Leadership, Arts & Culture..." value="<?= e($club['category']??'') ?>"></label><label>Faculty<select name="faculty" required><?php foreach(faculty_options() as $f): ?><option value="<?= e($f) ?>" <?= ($club['faculty']??'University-wide')===$f?'selected':'' ?>><?= e($f) ?></option><?php endforeach; ?></select></label><label>Description<textarea name="description" required minlength="20" maxlength="10000" rows="6"><?= e($club['description']??'') ?></textarea></label><label>Club contact email<input type="email" maxlength="190" name="contact_email" value="<?= e($club['contact_email']??'') ?>" placeholder="club@example.edu"></label><label>Assigned club leader<select name="leader_user_id"><option value="">Unassigned</option><?php foreach($leaders as $l): ?><option value="<?= (int)$l['id'] ?>" <?= (int)($club['leader_user_id']??0)===(int)$l['id']?'selected':'' ?>><?= e($l['full_name']) ?></option><?php endforeach; ?></select></label><div class="form-note">To assign a leader, first promote their account to <strong>club_leader</strong> in Admin → Users.</div><button class="btn btn-primary" type="submit">Save club</button></form></div></section>
